import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForEco3,validEco3,advanceEco3,numericEco3,ledgers,transferUnit,ledgerValid,decayRate,compostCases,milkData,mean,relativeRate,milkPH,milkRunValid,milkValid,milkGraphValid,scenarios,suitability}from './eco3-models.js?v=20261023-physicscomplete01';import{showEco3}from './eco3-visuals.js?v=20261023-physicscomplete01';export{showEco3};
export function mountEco3(l,p,root,{save,done,feedback}){let ts=tasksForEco3(l.widget.slice(5)),w=p.widget;w.eco3Task??=ts[0].id;w.eco3Drafts??={};w.eco3Passed??=[];let i=ts.findIndex(t=>t.id===w.eco3Task);if(i<0)i=0;let t=ts[i],v=w.eco3Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountEco3(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.eco3Passed.includes(t.id));
syncProcessMovie(l,1,!['carbon-process','water-process','decay-process','biogas-process','milk-process'].includes(t.kind)?{process:false}:null);
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('eco3Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('eco3Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealEco3">Reveal evidence →</button><p id="eco3Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showEco3(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#eco3Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validEco3(c,v.answer);}
else if(t.type==='sequence'){body=field('eco3Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advanceEco3">Advance pathway →</button><p id="eco3Readout" aria-live="polite"></p>';draw=()=>{showEco3(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#eco3Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='ledger'){let l=ledgers[t.ledger];v.counts??={...l.initial};v.observed??=[];body='<p>Closed material total: '+l.total+' units. Transfer one unit at a time.</p>'+field('eco3Move','Process',Object.entries(l.moves).map(([k,m])=>[k,m[2]]),v.move)+'<button class="secondary" id="eco3Transfer">Transfer one unit →</button><p id="eco3Observed"></p>'+field('eco3Reason','Interpretation',[['matter','Matter conserved; this is not an energy-recycling model'],['lost','Arrows destroy material'],['energy','Every unit is pure energy recycled forever']],v.reason);draw=()=>{showEco3(t.kind,{ledger:t.ledger,counts:v.counts,title:t.title});$('#eco3Observed').textContent='Transfers observed: '+v.observed.map(k=>l.moves[k][2]).join('; ');};valid=()=>ledgerValid(t.ledger,v);}
else if(t.type==='compost'){v.temp??='25';v.moisture??='moist';v.oxygen??='air';v.observed??=[];body=field('eco3Temp','Temperature',[['10','10°C'],['25','25°C'],['45','45°C']],v.temp)+field('eco3Moisture','Moisture',[['moist','Moist'],['dry','Dry']],v.moisture)+field('eco3Oxygen','Oxygen availability',[['air','Available'],['low','Limited']],v.oxygen)+'<label class="field-label" for="eco3Prediction">Predict mass-loss rate / g per day</label><input class="lab-input" id="eco3Prediction" type="number" value="'+(v.prediction??'')+'"><button class="secondary" id="eco3Run">Run ten-day model →</button><p id="eco3RunReadout"></p>';draw=()=>{showEco3(t.kind,{temp:v.temp,moisture:v.moisture,oxygen:v.oxygen,revealed:v.ran,title:t.title});$('#eco3RunReadout').textContent=v.ran?'Mass lost: '+decayRate(v.temp,v.moisture,v.oxygen)*10+' g in 10 days; compare with your predicted rate.':'Record baseline 25°C/moist/available oxygen, then 10°C, dry, limited oxygen and 45°C with other conditions at baseline.';};valid=()=>!!v.ran&&numericEco3(v.prediction,decayRate(v.temp,v.moisture,v.oxygen));}
else if(t.type==='milk'){v.temp??='20';v.elapsed??=0;v.observed??=[];body=field('eco3Temp','Water-bath temperature',[['20','20°C'],['35','35°C'],['50','50°C']],v.temp)+'<button class="secondary" id="eco3Clock">Advance virtual time 50 s →</button><p id="eco3MilkReadout"></p><label class="field-label" for="eco3Mean">Mean endpoint time / s</label><input class="lab-input" id="eco3Mean" type="number" value="'+(v.mean??'')+'"><label class="field-label" for="eco3Rate">Relative rate 1/mean time / s⁻¹</label><input class="lab-input" id="eco3Rate" type="number" step="any" value="'+(v.rate??'')+'"><button class="secondary" id="eco3RecordRun">Record temperature run</button><p id="eco3MilkProgress"></p>'+field('eco3Interpretation','Conclusion',[['limited','35°C is fastest among these tested fictional conditions'],['universal','35°C is the exact optimum for all natural decay'],['cells','1/time directly counts every microorganism']],v.interpretation);draw=()=>{showEco3('milk-data',{temp:v.temp,elapsed:v.elapsed,title:t.title});$('#eco3MilkReadout').textContent='Virtual time '+v.elapsed+' s; pH '+milkPH(v.temp,v.elapsed).toFixed(2)+(v.elapsed>=mean(milkData[v.temp])?'; endpoint repeats: '+milkData[v.temp].join(', ')+' s.':' · endpoint pH 7.2 not yet reached.');$('#eco3MilkProgress').textContent='Recorded: '+v.observed.map(t=>t+'°C').join(', ');};valid=()=>milkValid(v);}
else if(t.type==='milkgraph'){v.points??=Array(3).fill('');body='<p>Mean endpoint times: 20°C → 200 s; 35°C → 100 s; 50°C → 260 s.</p>'+field('eco3XAxis','Horizontal axis',[['temperature','Temperature / °C'],['time','Time / s']],v.xAxis)+field('eco3YAxis','Vertical axis',[['time','Mean endpoint time / s'],['temperature','Temperature / °C']],v.yAxis)+field('eco3Scale','Vertical maximum',[['100','100 s'],['300','300 s'],['200','200 s']],v.scale)+'<div class="eco2-input-grid">'+[20,35,50].map((n,j)=>'<label>Mean at '+n+'°C<input class="lab-input" type="number" id="eco3Point-'+j+'" value="'+v.points[j]+'"></label>').join('')+'</div>';draw=()=>showEco3(t.kind,{points:v.points,max:Number(v.scale||300),title:t.title});valid=()=>milkGraphValid(v);}
else if(t.type==='map'){v.scenario??='baseline';v.observed??=[];body='<p>Fictional plant limits: 10–20°C inclusive, water index≥4, CO₂ supply index≥300. Predict suitable sites, not actual abundance.</p>'+field('eco3Scenario','Scenario',Object.entries(scenarios).map(([k,c])=>[k,c.label]),v.scenario)+'<label class="field-label" for="eco3Prediction">Predict number of suitable model sites</label><input class="lab-input" id="eco3Prediction" type="number" value="'+(v.prediction??'')+'"><button class="secondary" id="eco3Run">Evaluate scenario →</button>';draw=()=>showEco3(t.kind,{scenario:v.scenario,revealed:v.ran,title:t.title});valid=()=>!!v.ran&&numericEco3(v.prediction,suitability(v.scenario).filter(s=>s.suitable).length);}

else{body='<p>'+t.prompt+'</p><label class="field-label" for="eco3Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="eco3Number" type="number" step="any" value="'+(v.number??'')+'">'+field('eco3Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showEco3(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericEco3(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="eco3Evidence"></p><div class="lab-actions"><button class="secondary" id="recordEco3">Record reasoning</button><button class="secondary" id="nextEco3">Next challenge →</button></div><p id="eco3Progress"></p>';
const status=()=>{$('#eco3Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):w.eco3Passed.includes(t.id)?'Challenge recorded.':'';if(['compost','map'].includes(t.type))$('#eco3Evidence').textContent='Recorded conditions: '+v.observed.join('; ');$('#eco3Progress').textContent=ts.filter(t=>w.eco3Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='eco3Case'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id.startsWith('eco3Point-')){v.points[Number(id.split('-')[1])]=val;save();draw();return;}let keys={eco3Move:'move',eco3Temp:'temp',eco3Moisture:'moisture',eco3Oxygen:'oxygen',eco3Prediction:'prediction',eco3Mean:'mean',eco3Rate:'rate',eco3Interpretation:'interpretation',eco3XAxis:'xAxis',eco3YAxis:'yAxis',eco3Scale:'scale',eco3Scenario:'scenario'};if(keys[id]){if(['eco3Temp','eco3Moisture','eco3Oxygen','eco3Scenario'].includes(id)){if(!val){remount();return;}v.ran=false;v.prediction='';v.elapsed=0;v.mean='';v.rate='';}v[keys[id]]=val;save();draw();return;}if(id==='eco3Answer')v.answer=val;else if(id==='eco3Next')v.next=val;else if(id==='eco3Number')v.number=val;else if(id==='eco3Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{let id=e.target.id;if(id.startsWith('eco3Point-')){v.points[Number(id.split('-')[1])]=e.target.value;draw();}else v[{eco3Prediction:'prediction',eco3Mean:'mean',eco3Rate:'rate'}[id]||'number']=e.target.value;save();};}

if($('#eco3Transfer'))$('#eco3Transfer').onclick=()=>{try{v.counts=transferUnit(t.ledger,v.counts,v.move);if(!v.observed.includes(v.move))v.observed.push(v.move);save();draw();feedback('One unit moved; the material total is conserved.');}catch(e){feedback(e.message,true);}};
if($('#eco3Run'))$('#eco3Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Make a numerical prediction first.',true);return;}v.ran=true;save();draw();feedback('Compare the model output with your prediction.');};
if($('#eco3Clock'))$('#eco3Clock').onclick=()=>{v.elapsed=Math.min(mean(milkData[v.temp]),v.elapsed+50);save();draw();};
if($('#eco3RecordRun'))$('#eco3RecordRun').onclick=()=>{if(!milkRunValid(v)){feedback('Reach the common endpoint, calculate the repeated mean and 1/mean time in s⁻¹.',true);return;}if(!v.observed.includes(v.temp))v.observed.push(v.temp);save();draw();feedback('Temperature run recorded. Compare the remaining temperatures.');};
if($('#revealEco3'))$('#revealEco3').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validEco3(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validEco3(t.cases[v.case],v.answer));};
if($('#advanceEco3'))$('#advanceEco3').onclick=()=>{let n=advanceEco3(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordEco3').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(['compost','map'].includes(t.type)){let key=t.type==='map'?v.scenario:v.temp+':'+v.moisture+':'+v.oxygen;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='compost'?compostCases.every(k=>v.observed.includes(k)):t.type==='map'?Object.keys(scenarios).every(k=>v.observed.includes(k)):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.eco3Passed.includes(t.id))w.eco3Passed.push(t.id);p.widgetDone=ts.every(t=>w.eco3Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':'Recorded. Compare the remaining scenarios.');};$('#nextEco3').onclick=()=>{if(!w.eco3Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.eco3Task=ts[(i+1)%ts.length].id;save();remount();};}
